def fill_business_details(apps, schema_editor):
    """Put the details from the business owner into the existing contact info row."""
    SiteInfo = apps.get_model("core", "SiteInfo")
    for info in SiteInfo.objects.all():
        if info.address in ("", "Cunningmore A, Mpumalanga"):
            info.address = "Stand No. 2300, Cunningmoore A Trust, Mkhuhlu, 1255"
        if not info.phone:
            info.phone = "072 880 5923"
        if not info.phone_2:
            info.phone_2 = "068 068 8359"
        if not info.trading_hours:
            info.trading_hours = "Monday to Sunday: 10:00 to 24:00\nPublic holidays: 10:00 to 24:00"
        info.save()


